const float biases_out[] = {
-0.000121652658f, 0.0202910919f, -0.0312050432f, 0.032043919f
};

void nn_linear(const float* weights, const float* biases, const float* input, int in_features, int out_features, float* output) {
    for (int i = 0; i < out_features; ++i) {
        float neuron = biases[i];
        for (int j = 0; j < in_features; ++j) {
            neuron += input[j] * weights[i * in_features + j];
        }
        output[i] = neuron;
    }
}

void nn_linear_nobias(const float* weights, const float* input, int in_features, int out_features, float* output) {
    for (int i = 0; i < out_features; ++i) {
        float neuron = 0.0f;
        for (int j = 0; j < in_features; ++j) {
            neuron += input[j] * weights[i * in_features + j];
        }
        output[i] = neuron;
    }
}

void nn_relu(float* input, int size) {
    for (int i = 0; i < size; ++i) {
        input[i] = fmaxf(0.0f, input[i]);
    }
}

static float nn_sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

void nn_reset_hidden(float* hidden) {
    memset(hidden, 0, NN_HIDDEN_DIM * sizeof(float));
}

static float enc_out[64];
static float gate_i[64];
static float gate_h[64];
static float gate_r[64];
static float gate_z[64];
static float head_out[64];

void nn_forward(const float* input, float* hidden, float* output) {
    // --- encoder ---------------------------------------------------
    nn_linear(weights_enc, biases_enc, input, 16, 64, enc_out);
    nn_relu(enc_out, 64);

    // --- GRU cell (flax.linen.GRUCell) -----------------------------
    // r = sigmoid(W_ir x + b_ir + W_hr h)
    nn_linear(weights_ir, biases_ir, enc_out, 64, 64, gate_i);
    nn_linear_nobias(weights_hr, hidden, 64, 64, gate_h);
    for (int i = 0; i < 64; ++i) { gate_r[i] = nn_sigmoid(gate_i[i] + gate_h[i]); }

    // z = sigmoid(W_iz x + b_iz + W_hz h)
    nn_linear(weights_iz, biases_iz, enc_out, 64, 64, gate_i);
    nn_linear_nobias(weights_hz, hidden, 64, 64, gate_h);
    for (int i = 0; i < 64; ++i) { gate_z[i] = nn_sigmoid(gate_i[i] + gate_h[i]); }

    // n = tanh(W_in x + b_in + r * (W_hn h + b_hn))
    nn_linear(weights_in, biases_in, enc_out, 64, 64, gate_i);
    nn_linear(weights_hn, biases_hn, hidden, 64, 64, gate_h);
    for (int i = 0; i < 64; ++i) {
        float n = tanhf(gate_i[i] + gate_r[i] * gate_h[i]);
        // h <- (1 - z) * n + z * h   (in place: this IS the new hidden state)
        hidden[i] = (1.0f - gate_z[i]) * n + gate_z[i] * hidden[i];
    }

    // --- head ------------------------------------------------------
    // The GRU output equals the new hidden state, so the head reads `hidden`.
    nn_linear(weights_head, biases_head, hidden, 64, 64, head_out);
    nn_relu(head_out, 64);
    nn_linear(weights_out, biases_out, head_out, 64, 4, output);
}
